        appendAgentMessage(
            AgentMessage(
                role: .user,
                text: RichAnswerVerificationFixture.question(for: scenario),
                source: "货币金融学课程 HTML"
            )
        )
        appendAgentMessage(
            AgentMessage(
                role: .assistant,
                text: presentation.narrative,
                source: "货币金融学课程 HTML",
                backend: .pi,
                richAnswer: presentation
            )
        )
        let familySummary = presentation.scenes.map(\.family.rawValue).joined(separator: ",")
