                && selectedItemID == baselineMaterialID
                && activeNotebookItemID == baselineNoteID
                && activeStudySessionID == baselineChatID
                && courseWorkspaceCourseID == courseA.id
            importedItems.removeAll { $0.id == missingMaterial.id }
