            let exactResumeMessages = activeSession.messages
            let materialBeforeExactResume = selectedItemID
            let locationBeforeExactResume = readerLocationID
            let noteBeforeExactResume = activeNotebookItemID
            courseResumePoints = [
                CourseResumePoint(
                    courseID: courseA.id,
