                && activeNotebookItemID == noteA.id
                && focusedPane == .agent
                && showAgent
                && layout.isDocumentThreePane
                && studySessions.count == sessionCount
                && threePaneOrder == paneOrder
            let saved = flushPendingWorkspaceSave()
