            courseID: otherCourseID,
            kind: .material,
            title: "同名但不属于该课的资料",
            label: "[材料：同名但不属于该课的资料]",
            excerpt: "不应打开。"
        )
        let missingSource = AgentReplySource(
            itemID: "missing-material",
            courseID: courseID,
            kind: .material,
            title: "已失效资料",
            label: "[材料：已失效资料]",
            excerpt: "不应打开。"
        )
        let movedSource = AgentReplySource(
            itemID: movedItem.id,
            courseID: courseID,
            kind: .material,
            title: movedItem.title,
            label: "[材料：\(movedItem.title)]",
            excerpt: "文件已经移走，不应显示可点击标签。"
        )
        await validateAgentReplySources(
            sources + [crossCourseSource, missingSource, movedSource]
        )
        let rejectsInvalidSources = !canOpenAgentReplySource(crossCourseSource)
            && !openAgentReplySource(crossCourseSource)
            && !canOpenAgentReplySource(missingSource)
            && !openAgentReplySource(missingSource)
            && !canOpenAgentReplySource(movedSource)
            && !openAgentReplySource(movedSource)
        let inline = AgentReplySourceInlinePresentation(
            text: replyText,
            sources: sources,
            language: interfaceLanguage
        )
        let firstSourceURL = URL(
            string: "weibei-source://\(sources[0].id.uuidString.lowercased())"
        )!
        let additionalSourceURL = URL(string: "weibei-source-group://0")!
        let inlineTagsWork = inline.source(for: firstSourceURL) == sources[0]
            && inline.additionalSources(for: additionalSourceURL)
                == [sources[2]]
            && inline.markdown.contains("+1")
        ChatSourceNavigationVerifier.reset()
        let openedHTML = openAgentReplySource(sources[1])
        let htmlRequested = openedHTML
            && activeStudySessionID == chatID
            && selectedItemID == htmlItem.id
            && readerTargetLocationID == htmlSectionLocationID
            && readerTargetLocationTitle == "实际利率"
            && readerSourceHighlight == sources[1].highlightQuery
        let htmlRendered = await waitForChatSourceVerification {
            self.selectedItemID == htmlItem.id
                && self.readerLocationID == htmlSectionLocationID
                && self.readerTargetLocationID == nil
        }
        let openedMarkdown = openAgentReplySource(sources[2])
        let markdownRequested = openedMarkdown
            && activeStudySessionID == chatID
            && selectedItemID == markdownItem.id
            && readerSourceHighlight == sources[2].highlightQuery
        let markdownRendered = await waitForChatSourceVerification {
            ChatSourceNavigationVerifier.foundMarkdown(
                itemID: markdownItem.id,
                query: sources[2].highlightQuery
            )
        }
        let opened = openAgentReplySource(sources[0])
        let pdfRendered = await waitForChatSourceVerification {
            self.selectedItemID == pdfItem.id
                && self.readerTargetPageIndex == nil
                && self.readerPageIndex == 0
        }
        let passed = rejectsInvalidSources
            && pdfReady
            && inlineTagsWork
            && htmlRequested
            && htmlRendered
            && markdownRequested
            && markdownRendered
            && opened
            && pdfRendered
            && activeStudySessionID == chatID
            && selectedItemID == pdfItem.id
            && showReader
            && showAgent
            && readerSourceHighlight == sources[0].highlightQuery
            && readerSourceHighlightPageIndex == 0
            && messages.last?.sources == sources
        save()
        let restored = WorkspaceStore(workspaceDirectory: workspaceDirectory)
        let reopenedReply = restored.studySessions
            .first(where: { $0.id == chatID })?
            .messages
            .last
        await restored.validateAgentReplySources(sources)
        let reopenedHTML = restored.openAgentReplySource(sources[1])
            && restored.activeStudySessionID == chatID
            && restored.selectedItemID == htmlItem.id
            && restored.readerTargetLocationID == htmlSectionLocationID
            && restored.readerSourceHighlight == sources[1].highlightQuery
        let reopenedMarkdown = restored.openAgentReplySource(sources[2])
            && restored.activeStudySessionID == chatID
            && restored.selectedItemID == markdownItem.id
            && restored.readerSourceHighlight == sources[2].highlightQuery
        let reopenedPDF = restored.openAgentReplySource(sources[0])
            && restored.activeStudySessionID == chatID
            && restored.selectedItemID == pdfItem.id
            && restored.readerTargetPageIndex == 0
            && restored.readerSourceHighlight == sources[0].highlightQuery
        let reopened = reopenedReply?.sources == sources
            && reopenedHTML
            && reopenedMarkdown
            && reopenedPDF
        let report = """
        result=\(passed && reopened ? "pass" : "fail")
        rejects_invalid=\(rejectsInvalidSources)
        pdf_ready=\(pdfReady)
        inline_tags=\(inlineTagsWork)
        html_requested=\(htmlRequested)
        html_rendered=\(htmlRendered)
        html_section_ids=\(ChatSourceNavigationVerifier.htmlSectionIDs.joined(separator: ","))
        html_active_id=\(ChatSourceNavigationVerifier.htmlActiveID ?? "")
        html_active_reason=\(ChatSourceNavigationVerifier.htmlActiveReason)
        markdown_requested=\(markdownRequested)
        markdown_rendered=\(markdownRendered)
        pdf_opened=\(opened)
        pdf_rendered=\(pdfRendered)
        reopened_sources=\(reopenedReply?.sources == sources)
        reopened_html=\(reopenedHTML)
        reopened_markdown=\(reopenedMarkdown)
        reopened_pdf=\(reopenedPDF)
        """
        try? "\(report)\n".write(
            to: workspaceDirectory.appendingPathComponent(
                "chat-source-navigation-report.txt"
            ),
            atomically: true,
            encoding: .utf8
        )
        recordVerificationStage("chat-source-navigation:\(passed)")
        if passed && reopened {
            let markerURL = storageURL.deletingLastPathComponent()
                .appendingPathComponent("chat-source-navigation-verified.txt")
            try? "Inline source tags survived reopen, kept Chat visible, and opened exact PDF, HTML, and Markdown locations\n"
                .write(to: markerURL, atomically: true, encoding: .utf8)
        }
        recordVerificationStage("completed")
    }

    private func waitForChatSourceVerification(
        _ condition: @MainActor () -> Bool
    ) async -> Bool {
        for _ in 0..<50 {
            if condition() { return true }
            try? await Task.sleep(nanoseconds: 100_000_000)
        }
        return false
    }

    private func configureEmptyWorkspaceVerificationScenario(_ scenario: String) {
        layout = .documentAgentNotes
        showLibrary = false
        agentSurface = .hidden
        appearanceMode = scenario.contains("dark") ? .inkstone : .paper
        showDailyInspiration = scenario != "empty-workspace-inspiration-off"

        if scenario.hasPrefix("empty-workspace-open-") {
            select(itemID: "sample-html")
            updateNote("# Empty workspace entry state marker\n\nPane toggles must preserve this note.\n")
        }

        showReader = false
        showAgent = false
        showNotes = false

        switch scenario {
        case "empty-workspace-open-doc":
            toggleReader()
        case "empty-workspace-open-chat":
            toggleAgent()
        case "empty-workspace-open-notes":
            toggleNotes()
        default:
            save()
        }
    }

    func replaceSelectionWithLastAgentAnswer() {
        guard selectionContext?.isReplaceableNoteSelection == true,
              let content = lastAgentAnswerContentForCurrentNote() else { return }
        noteEditorCommand = NoteEditorCommand(
            kind: .replaceSelection,
            markdown: content
        )
        focus(.notes)
    }

    func applyAgentPatchToEditor() {
        guard let content = lastAgentAnswerContentForCurrentNote() else { return }
        noteEditorCommand = NoteEditorCommand(kind: .applyAgentPatch, markdown: "\n\(noteBlockForAgentAnswer(content))")
        focus(.notes)
    }

    private func lastAgentAnswerContentForCurrentNote() -> String? {
        lastUsableAgentAnswer?.text
    }

    private func noteBlockForAgentAnswer(_ answer: String) -> String {
        let text = answer.trimmingCharacters(in: .whitespacesAndNewlines)
        if let suggestedNoteBlock = AgentOfflinePreview.suggestedNoteBlock(from: text, language: interfaceLanguage) {
            return suggestedNoteBlock
        }
        guard !text.hasPrefix("#") else { return text }
        return "## \(ui("整理建议", "Organization suggestion"))\n\(text)"
    }

    func submitAgentDraft() {
        if isAgentRunningInActiveChat {
            cancelAgentRequest()
            return
        }
        let question = agentDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !question.isEmpty, !isStoppingAgent else { return }
        if isAskingAgent {
            pendingAgentSwitchTargetID = activeStudySessionID
            isAgentSwitchConfirmationPresented = true
            return
        }
        askAgent()
    }

    func dismissAgentSwitchConfirmation() {
        isAgentSwitchConfirmationPresented = false
        pendingAgentSwitchTargetID = nil
    }

    func confirmAgentSwitchAndSend() {
        guard isAgentSwitchConfirmationPresented,
              let targetID = pendingAgentSwitchTargetID,
              activeStudySessionID == targetID,
              !agentDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        dismissAgentSwitchConfirmation()
        stopAgent(restoreDraft: false) { [weak self] in
            guard let self,
                  self.activeStudySessionID == targetID,
                  self.studySessions.contains(where: { $0.id == targetID }),
                  !self.agentDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
            self.askAgent()
        }
    }

    func askAgent() {
        flushStagedNoteDraftForAgentContext()
        guard agentRequestTask == nil,
              !isStoppingAgent,
              !isAskingAgent,
              !agentDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return }
        let question = agentDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        let target: AgentConversationTarget
        do {
            target = try agentConversationTarget()
        } catch {
            recordAgentTargetFailure(question: question, error: error)
            return
        }
        agentRequestTask = Task { @MainActor [weak self] in
            await self?.performAgentRequest(target: target)
        }
    }

    private func agentConversationTarget() throws -> AgentConversationTarget {
        guard let session = activeStudySession else {
            throw AgentConversationTargetError(
                message: ui(
                    "当前 Chat 尚未准备完成，请重新打开后再试。",
                    "The current Chat is not ready. Reopen it and try again."
                )
            )
        }
        guard session.scopeNeedsReview == false else {
            throw AgentConversationTargetError(
                message: ui(
                    "这个旧 Chat 还没有确认属于哪门课程，请先完成归类。",
                    "This older Chat still needs a confirmed course scope."
                )
            )
        }
        if let courseID = session.courseID {
            guard let course = course(withID: courseID),
                  let expectedIdentity = course.sourceRootIdentity,
                  let root = courseRootURL(for: courseID),
                  let resolvedRoot = try? CourseProjectPathPolicy.existingDirectory(root),
                  importedFileIdentityResolver(resolvedRoot) == expectedIdentity else {
                throw AgentConversationTargetError(
                    message: ui(
                        "这门课程的课程文件夹当前不可用，魏碑没有把问题发送到其他目录。",
                        "This course folder is unavailable. WeiBei did not send the question elsewhere."
                    )
                )
            }
            return AgentConversationTarget(
                sessionID: session.id,
                workingDirectory: resolvedRoot,
                courseID: courseID,
                courseRootIdentity: expectedIdentity
            )
        }

        let globalDirectory = workspaceDirectory
            .appendingPathComponent("AgentRuntime/GlobalWorkspace", isDirectory: true)
        do {
            try FileManager.default.createDirectory(
                at: globalDirectory,
                withIntermediateDirectories: true
            )
            try FileManager.default.setAttributes(
                [.posixPermissions: 0o700],
                ofItemAtPath: globalDirectory.path
            )
        } catch {
            throw AgentConversationTargetError(
                message: ui(
                    "魏碑无法准备全局 Chat 的本地工作目录：\(error.localizedDescription)",
                    "WeiBei could not prepare the global Chat workspace: \(error.localizedDescription)"
                )
            )
        }
        return AgentConversationTarget(
            sessionID: session.id,
            workingDirectory: globalDirectory,
            courseID: nil,
            courseRootIdentity: nil
        )
    }

    private func validateAgentConversationTarget(
        _ target: AgentConversationTarget,
        mustBeActive: Bool
    ) throws {
        guard let session = studySessions.first(where: { $0.id == target.sessionID }),
              session.courseID == target.courseID,
              (!mustBeActive || activeStudySessionID == target.sessionID) else {
            throw AgentConversationTargetError(
                message: ui(
                    mustBeActive
                        ? "发送前 Chat 已经切换，这条问题没有发到其他 Chat。"
                        : "原 Chat 已不存在，这条回答没有写到其他 Chat。",
                    mustBeActive
                        ? "The Chat changed before sending. This question was not sent to another Chat."
                        : "The original Chat no longer exists. This reply was not written to another Chat."
                )
            )
        }
        guard let courseID = target.courseID else { return }
        guard let expectedIdentity = target.courseRootIdentity,
              course(withID: courseID)?.sourceRootIdentity == expectedIdentity,
              let resolvedRoot = try? CourseProjectPathPolicy.existingDirectory(
                target.workingDirectory
              ),
              importedFileIdentityResolver(resolvedRoot) == expectedIdentity else {
            throw AgentConversationTargetError(
                message: ui(
                    "发送前课程文件夹发生了变化，魏碑没有让 Agent 在错误目录工作。",
                    "The course folder changed before sending. WeiBei did not run the Agent in the wrong directory."
                )
            )
        }
    }

    private func recordAgentTargetFailure(question: String, error: Error) {
        ensureActiveStudySession()
        guard let session = activeStudySession else { return }
        let requestID = UUID()
        let sourceTitle = agentMessageSourceTitle
        lastAgentFailureKind = .generic
        lastFailedAgentQuestion = question
        agentDraftsBySessionID[session.id] = question
        focusedPane = .agent
        let userMessage = AgentMessage(role: .user, text: question, source: sourceTitle)
        appendAgentMessage(userMessage)
        appendMessageToActiveSelectionAskThread(userMessage.id)
        let assistantMessage = AgentMessage(
            role: .assistant,
            text: AgentFailureKind.generic.userMessage(
                language: interfaceLanguage,
                detail: error.localizedDescription,
                draftPreserved: true
            ),
            source: sourceTitle,
            completionState: .interrupted,
            origin: AgentReplyOrigin(
                requestID: requestID,
                chatID: session.id,
                courseID: session.courseID
            ),
            failureKind: .generic,
            retryQuestion: question
        )
        appendAgentMessage(assistantMessage)
        appendMessageToActiveSelectionAskThread(assistantMessage.id)
        _ = flushPendingWorkspaceSave()
    }

    private func askAgentAndWait() async {
        askAgent()
        await agentRequestTask?.value
    }

    private func currentVisualAssetsForAgent(
        access: AgentProjectAccessSnapshot
    ) async -> [StudyAgentVisualAsset] {
        guard let item = selectedMaterialItem,
              !item.isNotebookNote,
              let source = access.sources.first(where: { $0.item.id == item.id }),
              let grant = source.grants.first(where: Self.agentFileGrantIsValid) else {
            return []
        }
        let mediaType: String
        switch grant.targetURL.pathExtension.lowercased() {
        case "jpg", "jpeg":
            mediaType = "image/jpeg"
        case "png":
            mediaType = "image/png"
        case "webp":
            mediaType = "image/webp"
        default:
            return []
        }
        let searchIndex = courseDocumentSearchIndex
        let snapshot = await Task.detached(priority: .userInitiated) {
            searchIndex.verifiedSnapshot(of: source.item, maximumBytes: 6_000_000)
        }.value
        guard let snapshot, Self.agentFileGrantIsValid(grant) else {
            if let snapshot {
                try? FileManager.default.removeItem(at: snapshot)
            }
            return []
        }
        return [
            StudyAgentVisualAsset(
                id: item.id,
                filePath: snapshot.path,
                mediaType: mediaType
            ),
        ]
    }

    private static func removeAgentVisualSnapshots(
        _ assets: [StudyAgentVisualAsset]
    ) {
        assets.forEach {
            try? FileManager.default.removeItem(atPath: $0.filePath)
        }
    }

    private func performAgentRequest(target: AgentConversationTarget) async {
        guard !Task.isCancelled, activeStudySessionID == target.sessionID else {
            agentRequestTask = nil
            return
        }
        flushStagedNoteDraftForAgentContext()
        let question = agentDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !question.isEmpty, !isAskingAgent else {
            agentRequestTask = nil
            return
        }
        do {
            try validateAgentConversationTarget(target, mustBeActive: true)
        } catch {
            recordAgentTargetFailure(question: question, error: error)
            agentRequestTask = nil
            return
        }

        persistCurrentNote()
        // Ensure live document selection is attached before we snapshot context for the request.
        if selectionAttachments.isEmpty,
           let selectionContext,
           !selectionContext.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            addSelectionAttachment(selectionContext)
        }
        let projectAccess = makeAgentProjectAccessSnapshot(target: target)
        let allowedItemIDs = Set(projectAccess.sources.map(\.item.id))
        let sentSelections = currentAgentSelections(allowedItemIDs: allowedItemIDs)
        let sentSelectionTitle = agentSelectionTitle(from: sentSelections)
        let sentSelectionText = agentSelectionText(from: sentSelections)
        let sentSelectionSources = agentSelectionSources(from: sentSelections)
        let sentSelectionIDs = Set(sentSelections.map(\.id))
        let shouldClearSentDocumentSelection = sentSelections.contains {
            $0.id == selectionContext?.id && $0.source == .document
        }
        let recentMessages = Array(messages.suffix(20))
        let sentMaterialItem: StudyItem? = selectedMaterialItem.flatMap { item in
            guard allowedItemIDs.contains(item.id) else { return nil }
            return item
        }
        let sentNoteItem: StudyItem? = activeNoteItem.flatMap { item in
            guard allowedItemIDs.contains(item.id) else { return nil }
            return item
        }
        let sourceTitle = sentMaterialItem != nil
            ? currentSourceReferenceTitle
            : sentNoteItem.map(displayTitle)
        let requestID = UUID()
        let requestWorkspaceRevision = agentContextRevision
        let requestMemoryScope = learningMemoryScope(courseID: target.courseID)
        let requestMemoryRevision = learningMemoryRevision(in: requestMemoryScope)
        let sentMaterialTitle = sentMaterialItem == nil
            ? ui("未选择材料", "No material selected")
            : currentSourceReferenceTitle
        let sentMaterialItemID = sentMaterialItem?.id
        let sentNoteTitle = sentNoteItem == nil
            ? ui("当前笔记", "Current Note")
            : agentNoteTitle
        let sentNoteText = sentNoteItem.flatMap { note in
            projectAccess.sources.first(where: { $0.item.id == note.id })?.memoryText
        } ?? ""
        let sentNoteItemID = sentNoteItem?.id
        let sentLearningContext = makeLearningContext(target: target)
        let sentVisualAssets = await currentVisualAssetsForAgent(access: projectAccess)
        defer { Self.removeAgentVisualSnapshots(sentVisualAssets) }
        let sentLanguage = interfaceLanguage
        let courseQuery = [question, sentSelectionText ?? "", String(sentNoteText.prefix(2_000))]
            .joined(separator: "\n\n")
        isAskingAgent = true
        activeAgentRequestID = requestID
        agentStreamingText = ""
        agentActivityText = ui("正在整理课程目录", "Indexing course")
        defer {
            if activeAgentRequestID == requestID {
                activeAgentRequestID = nil
                activeAgentReplyMessageID = nil
                activeAgentReplyChatID = nil
                isAskingAgent = false
                agentStreamingText = ""
                agentActivityText = nil
                agentRequestTask = nil
                // Answer finished: keep float pinned so the user can scroll the reply.
                if keepFloatingSelectionForAnswer, !isConversationSurfaceVisible {
                    pinnedFloatingAgent = true
                    agentSurface = .selectionFloat
                }
            }
        }

        var didAppendUserMessage = false
        var replyMessageID: UUID?
        do {
            let userMessage = AgentMessage(role: .user, text: question, source: sourceTitle)
            appendAgentMessage(userMessage)
            appendMessageToActiveSelectionAskThread(userMessage.id)
            didAppendUserMessage = true
            if let courseID = target.courseID {
                _ = captureCourseResumePoint(
                    courseID: courseID,
                    chatID: target.sessionID
                )
            }
            guard flushPendingWorkspaceSave() else {
                throw AgentConversationTargetError(
                    message: workspaceSaveError
                        ?? ui(
                            "问题尚未安全写入本地，魏碑没有把它发送给 Agent。",
                            "The question was not safely saved, so WeiBei did not send it to the Agent."
                        )
                )
            }

            let assistantMessage = AgentMessage(
                role: .assistant,
                text: "",
                source: sourceTitle,
                completionState: .generating,
                origin: AgentReplyOrigin(
                    requestID: requestID,
                    chatID: target.sessionID,
                    courseID: target.courseID
                ),
                retryQuestion: question
            )
            replyMessageID = assistantMessage.id
            activeAgentReplyMessageID = assistantMessage.id
            activeAgentReplyChatID = target.sessionID
            appendAgentMessage(assistantMessage)
            appendMessageToActiveSelectionAskThread(assistantMessage.id)
            guard flushPendingWorkspaceSave() else {
                throw AgentConversationTargetError(
                    message: workspaceSaveError
                        ?? ui(
                            "回答状态尚未安全写入本地，魏碑没有继续请求 Agent。",
                            "The reply state was not saved safely, so WeiBei did not continue the request."
                        )
                )
            }

            agentDraft = ""
            agentDraftsBySessionID[target.sessionID] = ""
            lastFailedAgentQuestion = nil
            lastAgentFailureKind = nil
            latestAgentNoteProposal = nil
            latestAgentLearningUpdate = nil
            if !sentSelectionIDs.isEmpty {
                withAnimation(WeiBeiMotion.panel) {
                    cancelPendingSelectionAttachment()
                    selectionAttachments.removeAll { sentSelectionIDs.contains($0.id) }
                    if selectionAttachments.isEmpty {
                        lastSelectionAttachmentDate = nil
                        lastSelectionUpdateDate = nil
                    }
                }
            }
            // Keep the floating selection agent open while answering — do not dismiss it mid-stream.
            if isConversationSurfaceVisible {
                agentSurface = .hidden
                keepFloatingSelectionForAnswer = false
                if shouldClearSentDocumentSelection, !pinnedFloatingAgent {
                    clearUnpinnedFloatingSelection(keepContext: false, invalidatesAgentContext: false)
                }
            } else if shouldClearSentDocumentSelection,
                      !keepFloatingSelectionForAnswer,
                      !pinnedFloatingAgent {
                clearUnpinnedFloatingSelection(
                    keepContext: false,
                    invalidatesAgentContext: false
                )
            } else if keepFloatingSelectionForAnswer || pinnedFloatingAgent {
                agentSurface = .selectionFloat
                pinnedFloatingAgent = true
            }

            let courseBuild = try await makeCourseContext(
                query: courseQuery,
                courseID: target.courseID,
                access: projectAccess
            )
            guard activeAgentRequestID == requestID else { return }
            try validateAgentConversationTarget(target, mustBeActive: false)
            let resolvedSentNoteText = courseBuild.selectedNoteText ?? ""
            let hostToolHandler = makeAgentHostToolHandler(
                target: target,
                access: projectAccess
            )
            let sourceReference = SourceReferenceTitle.parse(sentMaterialTitle)
            let request = StudyAgentRequest(
                id: requestID,
                purpose: .conversation,
                question: question,
                materialTitle: sentMaterialTitle,
                materialText: courseBuild.selectedMaterialText ?? "",
                materialIsTruncated: courseBuild.selectedMaterialIsTruncated,
                noteTitle: sentNoteTitle,
                noteText: resolvedSentNoteText,
                selectionTitle: sentSelectionTitle,
                selectionText: sentSelectionText,
                selectionSources: sentSelectionSources,
                recentMessages: recentMessages,
                courseContext: courseBuild.context,
                projectScope: projectAccess.scope,
                focus: StudyAgentFocus(
                    chatID: target.sessionID.uuidString.lowercased(),
                    courseID: target.courseID?.uuidString.lowercased(),
                    materialItemID: sentMaterialItemID,
                    materialTitle: sentMaterialItem.map(displayTitle),
                    pageIndex: sourceReference.pageIndex,
                    sectionTitle: sourceReference.sectionTitle,
                    sectionLocationID: sourceReference.sectionLocationID,
                    sectionOrdinal: sourceReference.sectionOrdinal,
                    selectionText: sentSelectionText,
                    actionSource: sentSelectionText == nil
                        ? (sentMaterialItem == nil ? "chat" : "reader")
                        : "selection"
                ),
                visualAssets: sentVisualAssets,
                learningContext: sentLearningContext,
                language: sentLanguage,
                contextRevision: "\(requestWorkspaceRevision):\(requestID.uuidString.lowercased())"
            )
            agentActivityText = ui("正在思考", "Thinking")
            if isGeneratingQuietInsight {
                await piRuntime.cancel()
            }
            let reply = try await executeStudyAgentRequest(
                request,
                target: target,
                replyMessageID: assistantMessage.id,
                hostToolHandler: hostToolHandler
            )
            guard activeAgentRequestID == request.id else { return }
            try validateAgentConversationTarget(target, mustBeActive: false)
            if activeStudySessionID == target.sessionID {
                latestAgentNoteProposal = reply.noteProposal
            }
            let memoryUpdate = applyLearningUpdate(
                reply.learningUpdate,
                expectedContextRevision: request.contextRevision,
                expectedMemoryRevision: requestMemoryRevision,
                expectedUserQuestion: request.question,
                target: target,
                messageID: assistantMessage.id
            )
            if activeStudySessionID == target.sessionID {
                lastAgentReplyContextRevision = requestWorkspaceRevision
            }
            var actions: [AgentReplyAction] = []
            if let proposal = reply.noteProposal,
               let sentNoteItemID {
                actions.append(
                    AgentReplyAction(
                        kind: .writeNote,
                        targetItemID: sentNoteItemID,
                        sourceItemID: sentMaterialItemID,
                        proposedMarkdown: proposal.markdown,
                        evidence: proposal.evidence,
                        contextRevision: proposal.contextRevision,
                        baselineContentDigest: Self.noteContentDigest(
                            Data(resolvedSentNoteText.utf8)
                        )
                    )
                )
            }
            if let proposal = reply.relationProposal {
                actions.append(
                    AgentReplyAction(
                        kind: .createRelation,
                        targetItemID: proposal.noteItemID,
                        sourceItemID: proposal.sourceItemID,
                        contextRevision: proposal.contextRevision
                    )
                )
            }
            let sources = reply.sources.map { source in
                var persisted = source
                persisted.courseID = target.courseID ?? persisted.courseID
                return persisted
            }
            if let messageID = replyMessageID {
                _ = updateAgentMessage(messageID, in: target.sessionID) {
                    $0.text = Self.mergedAgentReplyText(
                        streamed: $0.text,
                        final: reply.text
                    )
                    $0.backend = reply.backend
                    $0.richAnswer = reply.richAnswer
                    $0.completionState = .completed
                    $0.sources = sources
                    $0.actions = actions
                    $0.memoryUpdate = memoryUpdate
                    $0.failureKind = nil
                    $0.retryQuestion = nil
                    $0.toolTrace = reply.toolTrace
                }
            }
            // The visible reply is durable before this request is considered finished.
            // A save error must not replace or hide the answer that already arrived.
            _ = flushPendingWorkspaceSave()
        } catch PiAgentRuntimeError.cancelled, is CancellationError {
            guard activeAgentRequestID == requestID else { return }
            if let replyMessageID {
                interruptAgentReply(
                    requestID: requestID,
                    messageID: replyMessageID,
                    chatID: target.sessionID,
                    kind: .cancelled
                )
            }
            agentDraftsBySessionID[target.sessionID] = question
            if activeStudySessionID == target.sessionID,
               agentDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                agentDraft = question
                lastAgentFailureKind = .cancelled
            }
            return
        } catch {
            guard activeAgentRequestID == requestID else { return }
            if !didAppendUserMessage {
                appendAgentMessage(AgentMessage(role: .user, text: question, source: sourceTitle))
            }
            // Always restore the failed question so composer matches the failure copy.
            let kind = AgentFailureKind.classify(error)
            agentDraftsBySessionID[target.sessionID] = question
            if activeStudySessionID == target.sessionID {
                agentDraft = question
                focusedPane = .agent
                lastAgentFailureKind = kind
                lastFailedAgentQuestion = question
            }
            let detail = error.localizedDescription
            let failureText = kind.userMessage(
                language: interfaceLanguage,
                detail: detail,
                draftPreserved: true
            )
            if let replyMessageID {
                interruptAgentReply(
                    requestID: requestID,
                    messageID: replyMessageID,
                    chatID: target.sessionID,
                    kind: kind,
                    fallbackText: failureText
                )
            } else {
                appendAgentMessage(
                    AgentMessage(
                        role: .assistant,
                        text: failureText,
                        source: sourceTitle,
                        completionState: .interrupted,
                        origin: AgentReplyOrigin(
                            requestID: requestID,
                            chatID: target.sessionID,
                            courseID: target.courseID
                        ),
                        failureKind: kind,
                        retryQuestion: question
                    )
                )
            }
            _ = flushPendingWorkspaceSave()
        }

    }

    private func interruptAgentReply(
        requestID: UUID,
        messageID: UUID,
        chatID: UUID,
        kind: AgentFailureKind,
        fallbackText: String? = nil,
        restoreDraft: Bool = true
    ) {
        guard activeAgentRequestID == requestID,
              activeAgentReplyMessageID == messageID,
              activeAgentReplyChatID == chatID else { return }
        let updated = updateAgentMessage(messageID, in: chatID) {
            if $0.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
               let fallbackText {
                $0.text = fallbackText
            }
            $0.completionState = .interrupted
            $0.failureKind = kind
        }
        if restoreDraft, let question = updated?.retryQuestion {
            agentDraftsBySessionID[chatID] = question
        }
        guard activeStudySessionID == chatID else { return }
        lastAgentFailureKind = kind
        lastFailedAgentQuestion = updated?.retryQuestion
        if restoreDraft,
           agentDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
           let question = updated?.retryQuestion {
            agentDraft = question
        }
    }

    func cancelAgentRequest(restoreDraft: Bool = true) {
        stopAgent(restoreDraft: restoreDraft)
    }

    @discardableResult
    private func cancelAgentRequestIfRunning(
        in courseID: UUID,
        completion: (@MainActor () -> Void)? = nil
    ) -> Bool {
        guard let runningChatID = activeAgentReplyChatID,
              studySessions.first(where: { $0.id == runningChatID })?.courseID == courseID else {
            return false
        }
        stopAgent(restoreDraft: false, completion: completion)
        return true
    }

    private func stopAgent(
        restoreDraft: Bool,
        completion: (@MainActor () -> Void)? = nil
    ) {
        guard !isStoppingAgent,
              let requestID = activeAgentRequestID,
              let messageID = activeAgentReplyMessageID,
              let chatID = activeAgentReplyChatID else { return }
        interruptAgentReply(
            requestID: requestID,
            messageID: messageID,
            chatID: chatID,
            kind: .cancelled,
            restoreDraft: restoreDraft
        )
        let requestTask = agentRequestTask
        requestTask?.cancel()
        agentRequestTask = nil
        activeAgentRequestID = nil
        activeAgentReplyMessageID = nil
        activeAgentReplyChatID = nil
        isAskingAgent = false
        isStoppingAgent = true
        agentStreamingText = ""
        agentActivityText = nil
        agentStopTask?.cancel()
        agentStopTask = Task { @MainActor [weak self] in
            guard let self else { return }
            await self.piRuntime.cancel()
            await requestTask?.value
            self.isStoppingAgent = false
            self.agentStopTask = nil
            completion?()
        }
    }

    func retryAgentRequest(_ question: String) {
        guard !isAgentRunningInActiveChat, !isStoppingAgent else { return }
        let cleaned = question.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !cleaned.isEmpty else { return }
        agentDraft = cleaned
        lastFailedAgentQuestion = nil
        lastAgentFailureKind = nil
        submitAgentDraft()
    }

    func canRetryAgentRequest(question: String?, failureKind: AgentFailureKind?) -> Bool {
        guard !isAgentRunningInActiveChat, !isStoppingAgent else { return false }
        if let failureKind, !failureKind.isRetryable { return false }
        let question = (question ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return !question.isEmpty
    }

    static func isAgentFailureMessage(_ text: String) -> Bool {
        text.hasPrefix("请求失败")
            || text.hasPrefix("Agent 请求失败：")
            || text.hasPrefix("Request failed")
    }

    private func executeStudyAgentRequest(
        _ request: StudyAgentRequest,
        target: AgentConversationTarget,
        replyMessageID: UUID,
        hostToolHandler: @escaping StudyAgentHostToolHandler
    ) async throws -> StudyAgentReply {
        if capturesAgentRequestForSelfCheck,
           ProcessInfo.processInfo.arguments.contains("--self-check-course-project-root") {
            selfCheckCapturedAgentRequest = request
            return StudyAgentReply(
                text: "课程请求授权自检完成",
                backend: .pi
            )
        }
        let verificationScenario = Self.environmentValue(
            "WEIBEI_VERIFY_SCENARIO"
        )
        let isExplicitOfflineVerification =
            Self.environmentValue("WEIBEI_FORCE_OFFLINE_AGENT") == "1"
            && Self.environmentValue("WEIBEI_SUPPRESS_ACTIVATION") == "1"
            && (
                verificationScenario == "offline-learning-flow"
                    || verificationScenario == "course-home-flow"
            )
        if isExplicitOfflineVerification {
            return try await OfflineStudyAgentRuntime().respond(to: request)
        }

        let credential = resolvedAPIKey()
        var piFailure: Error?
        if Self.environmentValue("WEIBEI_PI_DISABLED") != "1" {
            let explicitProvider = Self.environmentValue("WEIBEI_PI_PROVIDER")
            let explicitModel = Self.environmentValue("WEIBEI_PI_MODEL")
            let thinking = Self.environmentValue("WEIBEI_PI_THINKING")
            let selectedProvider = agentProviderID
            WeiBeiAgentDataPaths.migrateHomePiAuthIfNeeded()
            let linkedOAuth = PiOAuthService.readLinkedOAuthProviders(
                from: WeiBeiAgentDataPaths.piAuthJSON
            )
            // Prefer explicit Pi provider id; map legacy OpenAI API selection to openai-codex when OAuth-linked.
            let providerName: String = {
                if !explicitProvider.isEmpty { return explicitProvider }
                if selectedProvider == .openaiCodex { return "openai-codex" }
                if selectedProvider == .openai, linkedOAuth.contains("openai-codex"), agentAuthMethod == .subscription {
                    return "openai-codex"
                }
                return selectedProvider.piProviderName
            }()
            // OAuth tokens live in auth.json — do not force API key env when subscription is active.
            let usesOAuth = linkedOAuth.contains(providerName)
                || (providerName == "openai-codex" && linkedOAuth.contains("openai-codex"))
            let configuration = PiAgentProviderConfiguration(
                provider: providerName,
                model: explicitModel.isEmpty ? resolvedModelName : explicitModel,
                apiKey: usesOAuth ? nil : credential?.key,
                baseURL: agentBaseURL.isEmpty ? nil : agentBaseURL,
                thinkingLevel: thinking.isEmpty ? "medium" : thinking
            )
            await piRuntime.configure(configuration)
            await piRuntime.writeCustomModelsJSONIfNeeded(
                providerID: selectedProvider,
                baseURL: agentBaseURL,
                model: resolvedModelName
            )
            do {
                return try await piRuntime.respond(
                    to: request,
                    sessionID: target.sessionID,
                    workingDirectory: target.workingDirectory,
                    hostToolHandler: hostToolHandler
                ) { [weak self] progress in
                    await self?.applyAgentProgress(
                        progress,
                        requestID: request.id,
                        replyMessageID: replyMessageID,
                        chatID: target.sessionID
                    )
                }
            } catch let error as PiAgentRuntimeError {
                if error == .cancelled || Task.isCancelled {
                    throw PiAgentRuntimeError.cancelled
                }
                guard error.permitsAutomaticFallback else { throw error }
                piFailure = error
                openAIKeyStatus = ui(
                    "PI 暂不可用：\(error.localizedDescription)",
                    "PI is unavailable: \(error.localizedDescription)"
                )
            } catch {
                if Task.isCancelled { throw PiAgentRuntimeError.cancelled }
                piFailure = error
                openAIKeyStatus = ui(
                    "PI 暂不可用：\(error.localizedDescription)",
                    "PI is unavailable: \(error.localizedDescription)"
                )
            }
        }

        if request.purpose == .conversation {
            throw piFailure ?? PiAgentRuntimeError.unavailable
        }

        // OpenAI HTTP fallback only for the openai provider; other providers go Offline with a clear note.
        if agentProviderID.supportsOpenAIHTTPFallback, let credential {
            do {
                let client = OpenAIResponsesClient(apiKey: credential.key, model: resolvedModelName)
                return try await client.respond(to: request) { [weak self] progress in
                    await self?.applyAgentProgress(
                        progress,
                        requestID: request.id,
                        replyMessageID: replyMessageID,
                        chatID: target.sessionID
                    )
                }
            } catch is CancellationError {
                throw PiAgentRuntimeError.cancelled
            } catch {
                if Task.isCancelled { throw PiAgentRuntimeError.cancelled }
                openAIKeyStatus = ui(
                    "在线请求失败，已改用离线草稿：\(error.localizedDescription)",
                    "Online request failed; using an offline draft: \(error.localizedDescription)"
                )
            }
        } else if !agentProviderID.supportsOpenAIHTTPFallback {
            openAIKeyStatus = ui(
                "当前提供商不支持 OpenAI HTTP 回退，已改用离线草稿。",
                "This provider has no OpenAI HTTP fallback; using an offline draft."
            )
        } else {
            openAIKeyStatus = ui(
                "PI 与在线密钥均不可用，当前使用离线草稿。",
                "PI and an online key are unavailable; using an offline draft."
            )
        }

        return try await OfflineStudyAgentRuntime().respond(to: request) { [weak self] progress in
            await self?.applyAgentProgress(
                progress,
                requestID: request.id,
                replyMessageID: replyMessageID,
                chatID: target.sessionID
            )
        }
    }

    func shutdownAgentRuntime() {
        agentRequestTask?.cancel()
        agentStopTask?.cancel()
        quietInsightTask?.cancel()
        let runtime = piRuntime
        let completion = DispatchSemaphore(value: 0)
        Task.detached {
            await runtime.shutdown()
            completion.signal()
        }
        _ = completion.wait(timeout: .now() + 1)
    }

    private func applyAgentProgress(
        _ progress: StudyAgentProgress,
        requestID: UUID,
        replyMessageID: UUID,
        chatID: UUID
    ) {
        guard activeAgentRequestID == requestID,
              activeAgentReplyMessageID == replyMessageID,
              activeAgentReplyChatID == chatID else { return }
        let updatesVisibleChat = activeStudySessionID == chatID
        switch progress {
        case .preparing:
            if updatesVisibleChat {
                agentActivityText = ui("正在思考", "Thinking")
            }
        case let .usingTool(name):
            guard updatesVisibleChat else { return }
            switch name {
            case "weibei_context":
                agentActivityText = ui("正在核对材料与笔记", "Checking material and notes")
            case "weibei_course_map", "weibei_course_search", "weibei_course_read",
                 "ls", "find", "grep", "read":
                agentActivityText = ui("正在查找课程关联", "Finding course connections")
            case "weibei_learning_memory":
                agentActivityText = ui("正在回顾学习记忆", "Reviewing learning memory")
            case "weibei_learning_update":
                agentActivityText = ui("正在整理学习进展", "Updating study progress")
            case "weibei_note_proposal":
                agentActivityText = ui("正在整理写入建议", "Preparing a note proposal")
            case "weibei_rich_answer":
                agentActivityText = ui("正在组织富回答", "Building a rich answer")
            default:
                agentActivityText = ui("正在处理", "Working")
            }
        case let .text(text):
            if updatesVisibleChat {
                agentStreamingText = text
            }
            _ = updateAgentMessage(replyMessageID, in: chatID) {
                $0.text = text
                $0.backend = .pi
            }
            if updatesVisibleChat {
                agentActivityText = ui("正在组织回答", "Composing answer")
            }
        }
    }

